cases.tests:
assert rle_encode('') == ''
assert rle_encode('aaabb') == '3a2b'
assert rle_encode('abc') == '1a1b1c'
assert rle_decode('') == ''
assert rle_decode('3a2b') == 'aaabb'
assert rle_decode(rle_encode('mississippi')) == 'mississippi'
for bad in ('3', 'a2', '2ab', '0a'):
    try:
        rle_decode(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(bad + ' must raise ValueError')

text = '\n'.join([
    '; comment',
    'name = root',
    '[db]',
    'host=localhost',
    'port = 5432',
    '# note',
    '[app]',
    'debug = false',
    'name = app',
])
got = parse_ini(text)
assert got[''] == {'name': 'root'}
assert got['db'] == {'host': 'localhost', 'port': '5432'}
assert got['app'] == {'debug': 'false', 'name': 'app'}
try:
    parse_ini('[x]\nbroken line\n')
except ValueError:
    pass
else:
    raise AssertionError('malformed line must raise ValueError')

assert split_csv_line('a,b,c') == ['a', 'b', 'c']
assert split_csv_line('a,"b,c",d') == ['a', 'b,c', 'd']
assert split_csv_line('"he said ""hi""",x') == ['he said "hi"', 'x']
assert split_csv_line('') == ['']
try:
    split_csv_line('"unterminated,x')
except ValueError:
    pass
else:
    raise AssertionError('unbalanced quote must raise ValueError')

